function setLanguage(lang){state.lang=lang;document.documentElement.lang=lang;$$('[data-i18n]').forEach(el=>{const value=t(el.dataset.i18n);if(value!==el.dataset.i18n)el.innerHTML=value;});$$('[data-placeholder]').forEach(el=>{el.placeholder=t(el.dataset.placeholder);});$('#language').textContent=lang==='en'?'FR':'EN';$('#language').setAttribute('aria-label',lang==='en'?'Afficher le site en français':'Display this website in English');$('#menu-toggle').setAttribute('aria-label',lang==='en'?'Toggle navigation':'Afficher la navigation');$('#close-dialog').setAttribute('aria-label',lang==='en'?'Close citation':'Fermer la référence');$$('[data-kind]').forEach(el=>el.textContent=lang==='fr'?kindFr[el.dataset.kind]:el.dataset.kind);$$('[data-topic]').forEach(el=>el.textContent=lang==='fr'?topicFr[el.dataset.topic]:el.dataset.topic);$$('#topic option').forEach(el=>{if(el.value)el.textContent=lang==='fr'?topicFr[el.value]:el.value;});try{localStorage.setItem('research-language',lang);}catch{}applyFilters(false);}
$('#language').addEventListener('click',()=>setLanguage(state.lang==='en'?'fr':'en'));
const fold=s=>s.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function isLibrary(p,name){if(name==='IEEE')return p.doi.startsWith('10.1109/')||p.doi.startsWith('10.23919/');if(name==='IOP')return p.doi.startsWith('10.1088/');if(name==='Springer')return p.doi.startsWith('10.1007/');if(name==='Wiley')return p.doi.startsWith('10.1002/');if(name==='Zenodo')return p.doi.startsWith('10.5281/');return true;}
function matching(){const words=fold($('#search').value.trim()).split(/\s+/).filter(Boolean);const year=$('#year').value,topic=$('#topic').value;return publications.filter(p=>(!state.type||p.kind===state.type)&&(!year||String(p.year)===year)&&(!topic||p.topic===topic)&&isLibrary(p,state.library)&&words.every(w=>fold([p.title,p.venue,p.registeredVenue||'',...p.authors,p.topic,p.doi,topicFr[p.topic]||''].join(' ')).includes(w))).sort((a,b)=>$('#sort').value==='oldest'?a.year-b.year:$('#sort').value==='newest'?b.year-a.year:$('#sort').value==='crossref'?(b.crossrefCitations??-1)-(a.crossrefCitations??-1)||b.year-a.year:(b.scholarCitations??-1)-(a.scholarCitations??-1)||b.year-a.year);}
function applyFilters(updateUrl=true){const found=matching();const visible=new Set(found.slice(0,state.limit).map(p=>p.id));const rows=new Map($$('.pub').map(el=>[el.dataset.id,el]));$$('.pub').forEach(el=>el.hidden=!visible.has(el.dataset.id));found.forEach(p=>$('#publication-list').append(rows.get(p.id)));$('#empty').hidden=found.length>0;$('#show-more').hidden=found.length<=state.limit;$('#export-all').disabled=!found.length;$('#results-count').textContent=`${found.length} ${t('records')} · ${Math.min(found.length,state.limit)} ${t('shown')}${state.library?' · '+t('library')+': '+state.library:''}`;$$('[data-type]').forEach(el=>{const active=el.dataset.type===state.type;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});if(updateUrl){const u=new URL(location.href);for(const [k,v] of Object.entries({q:$('#search').value.trim(),year:$('#year').value,topic:$('#topic').value,type:state.type,source:state.library,sort:$('#sort').value==='citations'?'':$('#sort').value})){if(v)u.searchParams.set(k,v);else u.searchParams.delete(k);}history.replaceState(null,'',u);}}
function changeFilter(){state.limit=8;applyFilters();}
for(const id of ['search','year','topic','sort'])$('#'+id).addEventListener(id==='search'?'input':'change',changeFilter);
$$('[data-type]').forEach(el=>el.addEventListener('click',()=>{state.type=el.dataset.type;changeFilter();}));
function reset(){state.type='';state.library='';state.limit=8;$('#search').value='';$('#year').value='';$('#topic').value='';$('#sort').value='citations';applyFilters();}
$('#reset').addEventListener('click',reset);$('#empty-reset').addEventListener('click',reset);
$('#show-more').addEventListener('click',()=>{const first=matching()[state.limit];state.limit+=8;applyFilters(false);if(first){const el=$(`[data-id="${first.id}"] h3 a`);el.focus({preventScroll:true});}});
$$('[data-research]').forEach(el=>el.addEventListener('click',()=>{reset();$('#topic').value=el.dataset.research;changeFilter();}));
$$('[data-library]').forEach(el=>el.addEventListener('click',()=>{reset();state.library=el.dataset.library;changeFilter();$('#publications').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
function bibtex(p){const type=p.kind==='Journal article'?'article':p.kind==='Book chapter'?'incollection':p.kind==='Conference paper'?'inproceedings':'misc';const escape=s=>String(s).replace(/\\/g,'\\textbackslash{}').replace(/[{}]/g,m=>'\\'+m).replace(/&/g,'\\&');const fields={title:p.title,year:p.year};if(p.authors.length)fields.author=p.authors.map(n=>{const parts=n.split(' ');return parts.pop()+', '+parts.join(' ');}).join(' and ');fields[type==='article'?'journal':'booktitle']=p.registeredVenue||p.venue;if(p.volume)fields.volume=p.volume;if(p.issue)fields.number=p.issue;if(p.pages)fields.pages=p.pages.replace(/[–—]/g,'--');if(p.doi)fields.doi=p.doi;fields.url=p.doi?'https://doi.org/'+p.doi:p.source;if(p.note)fields.note=p.note;if(type==='misc')delete fields.booktitle;return `@${type}{benzater${p.year}${p.id},\n${Object.entries(fields).map(([k,v])=>`  ${k} = {${escape(v)}}`).join(',\n')}\n}`;}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
async function copy(text,field){try{await navigator.clipboard.writeText(text);toast(t('copied'));return true;}catch{if(field){field.focus();field.select();toast(t('copyFailed'));return false;}const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.top='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?t('copied'):t('copyFailed'));return ok;}}
function download(text,name,type='application/x-bibtex'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#publication-list').addEventListener('click',e=>{const btn=e.target.closest('[data-cite]');if(!btn)return;state.current=publications.find(p=>p.id===btn.dataset.cite);$('#citation-work').textContent=state.current.title;$('#citation-text').value=bibtex(state.current);$('#citation-dialog').showModal();});
$('#close-dialog').addEventListener('click',()=>$('#citation-dialog').close());$('#citation-dialog').addEventListener('click',e=>{if(e.target===$('#citation-dialog')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close();}});
$('#copy-citation').addEventListener('click',()=>copy($('#citation-text').value,$('#citation-text')));$('#download-citation').addEventListener('click',()=>download(bibtex(state.current),`benzater-${state.current.id}-${state.current.year}.bib`));
$('#export-all').addEventListener('click',()=>{const found=matching();download(found.map(bibtex).join('\n\n')+'\n','benzater-publications.bib');toast(t('exported'));});
$('#copy-email').addEventListener('click',()=>copy('benzater.hadj@gmail.com'));
$('#menu-toggle').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$$('#navigation a').forEach(el=>el.addEventListener('click',()=>{$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
const params=new URLSearchParams(location.search);$('#search').value=params.get('q')||'';for(const k of ['year','topic']){const value=params.get(k)||'';if([...$('#'+k).options].some(o=>o.value===value))$('#'+k).value=value;}if($$('[data-type]').some(el=>el.dataset.type===params.get('type')))state.type=params.get('type');if(['IEEE','IOP','Springer','Wiley','Zenodo'].includes(params.get('source')))state.library=params.get('source');if(['citations','crossref','newest','oldest'].includes(params.get('sort')))$('#sort').value=params.get('sort');let savedLang='en';try{savedLang=localStorage.getItem('research-language')||'en';}catch{}setLanguage(savedLang==='fr'?'fr':'en');

